'use strict';
/**
 * EMCAP workbook regeneration pipeline test (pure -- no DB, no network).
 *
 * Proves the OWNER'S CONTRACT for scripts/emcap-regenerate-fixture.js:
 *
 *  (1) REPRODUCIBILITY -- the committed rate fixture
 *      (scripts/fixtures/emcap-pricing-tool-v1.json) and the frozen engine's
 *      RATE_BLOCKS + TG literals are regenerated BYTE-IDENTICAL from the
 *      archived source workbook scripts/fixtures/EMCAP_Pricing_Tool_v1.xlsx
 *      (sha256-pinned), so "give me a new Excel sheet and update the pricing"
 *      is a mechanical step, not an archaeology project.
 *
 *  (2) SENSITIVITY -- mutating a single rate cell in an in-memory copy of the
 *      workbook makes the check FAIL, NAMING THE KEY: once in the fixture
 *      diff (hidden Engine sheet) and once in the cross-source verifier
 *      (tab 2 vs Engine sheet), and the CLI exits non-zero.
 *
 *  (3) SAFETY -- the default CLI run is check-only (writes nothing), and
 *      --write refuses while the cross-source check reports an UNEXPECTED
 *      Engine-vs-tab-2 divergence.
 *
 * Run: node scripts/test-emcap-regenerate-pure.js
 */

const fs = require('fs');
const os = require('os');
const path = require('path');
const zlib = require('zlib');
const crypto = require('crypto');
const { spawnSync } = require('child_process');

const REGEN_PATH = path.join(__dirname, 'emcap-regenerate-fixture.js');
const REGEN = require(REGEN_PATH);

let passed = 0;
function ok(cond, msg) {
  if (!cond) { console.error('FAIL:', msg); process.exitCode = 1; throw new Error(msg); }
  passed++;
}
function section(name) { console.log('--- ' + name); }

/* CRC32 (IEEE): node:zlib exposes crc32 from v20.15; fall back to a table
   implementation so the test honors package.json "engines": ">=18". */
const crc32 = (() => {
  if (typeof zlib.crc32 === 'function') return (buf) => zlib.crc32(buf) >>> 0;
  const table = new Uint32Array(256);
  for (let n = 0; n < 256; n++) {
    let c = n;
    for (let k = 0; k < 8; k++) c = c & 1 ? 0xedb88320 ^ (c >>> 1) : c >>> 1;
    table[n] = c >>> 0;
  }
  return (buf) => {
    let c = 0xffffffff;
    for (let i = 0; i < buf.length; i++) c = table[(c ^ buf[i]) & 0xff] ^ (c >>> 8);
    return (c ^ 0xffffffff) >>> 0;
  };
})();

/* Minimal STORE-method ZIP writer (test-side only, for the in-memory mutation). */
function writeZipStored(entries) {
  const locals = [];
  const files = [];
  let offset = 0;
  for (const [name, data] of entries) {
    const nameBuf = Buffer.from(name, 'utf8');
    const crc = crc32(data);
    const lh = Buffer.alloc(30);
    lh.writeUInt32LE(0x04034b50, 0);
    lh.writeUInt16LE(20, 4);      // version needed
    lh.writeUInt16LE(0, 6);       // flags
    lh.writeUInt16LE(0, 8);       // method 0 = store
    lh.writeUInt16LE(0, 10);      // time
    lh.writeUInt16LE(0, 12);      // date
    lh.writeUInt32LE(crc, 14);
    lh.writeUInt32LE(data.length, 18);
    lh.writeUInt32LE(data.length, 22);
    lh.writeUInt16LE(nameBuf.length, 26);
    lh.writeUInt16LE(0, 28);      // extra len
    locals.push(lh, nameBuf, data);
    files.push({ nameBuf, crc, size: data.length, offset });
    offset += 30 + nameBuf.length + data.length;
  }
  const cds = [];
  let cdSize = 0;
  for (const f of files) {
    const cd = Buffer.alloc(46);
    cd.writeUInt32LE(0x02014b50, 0);
    cd.writeUInt16LE(20, 4);
    cd.writeUInt16LE(20, 6);
    cd.writeUInt32LE(f.crc, 16);
    cd.writeUInt32LE(f.size, 20);
    cd.writeUInt32LE(f.size, 24);
    cd.writeUInt16LE(f.nameBuf.length, 28);
    cd.writeUInt32LE(f.offset, 42);
    cds.push(cd, f.nameBuf);
    cdSize += 46 + f.nameBuf.length;
  }
  const eocd = Buffer.alloc(22);
  eocd.writeUInt32LE(0x06054b50, 0);
  eocd.writeUInt16LE(files.length, 8);
  eocd.writeUInt16LE(files.length, 10);
  eocd.writeUInt32LE(cdSize, 12);
  eocd.writeUInt32LE(offset, 16);
  return Buffer.concat([...locals, ...cds, eocd]);
}

/** Replace the cached <v> of one cell in one worksheet XML buffer. */
function mutateCellValue(entries, sheetEntry, cellRef, newValueText) {
  const xml = entries.get(sheetEntry).toString('utf8');
  const cellRe = new RegExp('(<c r="' + cellRef + '"[^>]*>)([\\s\\S]*?)(</c>)');
  const m = cellRe.exec(xml);
  if (!m) throw new Error('mutation: cell ' + cellRef + ' not found in ' + sheetEntry);
  if (!/<v>[\s\S]*?<\/v>/.test(m[2])) throw new Error('mutation: cell ' + cellRef + ' has no cached <v>');
  const inner = m[2].replace(/<v>[\s\S]*?<\/v>/, '<v>' + newValueText + '</v>');
  const out = new Map(entries);
  out.set(sheetEntry, Buffer.from(xml.replace(cellRe, (m[1] + inner + m[3]).replace(/\$/g, '$$$$')), 'utf8'));
  return out;
}

function runCli(args) {
  const r = spawnSync(process.execPath, [REGEN_PATH, ...args], { encoding: 'utf8' });
  return { status: r.status, out: String(r.stdout || '') + String(r.stderr || '') };
}

const tmpDir = fs.mkdtempSync(path.join(os.tmpdir(), 'emcap-regen-test-'));
try {
  /* ================= (0) archive integrity ================= */
  section('archived workbook');
  ok(fs.existsSync(REGEN.ARCHIVE_XLSX), 'archived workbook exists at ' + REGEN.ARCHIVE_XLSX);
  const archiveBuf = fs.readFileSync(REGEN.ARCHIVE_XLSX);
  const sha = crypto.createHash('sha256').update(archiveBuf).digest('hex');
  ok(sha === REGEN.ARCHIVE_SHA256, 'archived workbook sha256 matches the recorded hash (' + sha + ')');

  /* ================= (1) clean CLI runs, check-only default ================= */
  section('CLI: default run is check-only and CLEAN');
  const fixtureBytesBefore = fs.readFileSync(REGEN.FIXTURE_PATH);
  const engineBytesBefore = fs.readFileSync(path.join(__dirname, '..', 'web', 'v2', 'tools', 'silver-program.js'));
  const def = runCli([]);
  ok(def.status === 0, 'default run exits 0 (got ' + def.status + ')\n' + def.out);
  ok(/BYTE-IDENTICAL/.test(def.out), 'default run reports the fixture byte-identical');
  ok(/84 bridge_ar_7501 \+ 167 refi24 = 251/.test(def.out), 'default run reports the expected 251-cell Engine-vs-tab-2 contract (84 + 167)');
  ok(/RESULT: CLEAN/.test(def.out), 'default run reports CLEAN');
  ok(fs.readFileSync(REGEN.FIXTURE_PATH).equals(fixtureBytesBefore), 'default run wrote NOTHING to the committed fixture');
  ok(fs.readFileSync(path.join(__dirname, '..', 'web', 'v2', 'tools', 'silver-program.js')).equals(engineBytesBefore), 'default run wrote NOTHING to the engine');
  ok(runCli(['--check']).status === 0, 'explicit --check exits 0');
  ok(runCli(['--blocks']).status === 0, 'explicit --blocks exits 0');

  /* ================= (2) module-level reproducibility ================= */
  section('module: extraction reproduces the committed artifacts');
  const wb = REGEN.readWorkbook(archiveBuf);
  ok(Object.keys(wb.fixture.rates).length === 1555, 'Engine sheet yields 1,555 rate keys');
  ok(Object.keys(wb.fixture.tierGrid).length === 18, 'Engine sheet yields 18 tier-grid rows');
  const committedText = fs.readFileSync(REGEN.FIXTURE_PATH, 'utf8');
  ok(REGEN.serializeFixture(wb.fixture) === committedText, 'serializeFixture() output is byte-identical to the committed fixture');
  const rb = REGEN.compileRateBlocks(wb.fixture.rates);
  ok(rb.blockCount === 112, 'compiled RATE_BLOCKS has 112 blocks (got ' + rb.blockCount + ')');
  for (const rel of REGEN.ENGINE_COPIES) {
    const text = fs.readFileSync(path.join(__dirname, '..', rel), 'utf8');
    ok(REGEN.extractLiteral(text, '    var RATE_BLOCKS = {') === rb.literal, rel + ': live RATE_BLOCKS literal matches the compiled one');
    ok(REGEN.extractLiteral(text, '  var TG = {') === REGEN.compileTg(wb.fixture.tierGrid).literal, rel + ': live TG literal matches the compiled one');
  }
  const bc = REGEN.blocksCheck(wb);
  ok(bc.ok, 'blocksCheck (string + semantic) is clean: ' + JSON.stringify(bc.problems.slice(0, 3)));
  const cross = REGEN.crossSourceCheck(wb.fixture.rates, wb.matrix);
  ok(cross.ok, 'crossSourceCheck is clean: ' + JSON.stringify(cross.problems.slice(0, 3)));
  ok(cross.expectedCounts.bridge_ar_7501 === 84 && cross.expectedCounts.refi24 === 167, 'expected-difference classes count 84 + 167');
  ok(cross.sharedCount === 1555, 'tab 2 shares exactly the 1,555 Engine-sheet cells');

  /* ================= (3) mutation A: one Engine-sheet rate cell ================= */
  section('mutation: one Engine-sheet rate cell FAILS the check, naming the key');
  const KEY = 'STD|S|FF|P|12|T1|<64.99%|FICO 700+|<74.99%';
  ok(wb.fixture.rates[KEY] === 0.08, 'target key prices 8.00% in the pristine workbook');
  const entries = REGEN.readZipEntries(archiveBuf);
  const sheets = REGEN.workbookSheetMap(entries);
  const engineEntry = sheets.find((s) => s.name === 'Engine').entry;
  const matrixEntry = sheets.find((s) => s.name === 'EMCAP_Pricing Matrix').entry;
  // locate the key's row on the Engine sheet via its shared-string index
  const strings = REGEN.loadSharedStrings(entries);
  const ssIdx = strings.indexOf(KEY);
  ok(ssIdx >= 0, 'target key found in sharedStrings');
  const engXml = entries.get(engineEntry).toString('utf8');
  const rowM = new RegExp('<c r="A(\\d+)"[^>]*><v>' + ssIdx + '</v>').exec(engXml);
  ok(rowM, 'target key row located on the Engine sheet');
  const engRow = rowM[1];

  const mutatedA = writeZipStored(mutateCellValue(entries, engineEntry, 'B' + engRow, '0.5'));
  const wbA = REGEN.readWorkbook(mutatedA);
  ok(wbA.fixture.rates[KEY] === 0.5, 'mutated workbook reads 0.5 for the target key');
  const fxA = REGEN.fixtureCheck(wbA, REGEN.FIXTURE_PATH);
  ok(!fxA.ok, 'fixture check FAILS on the mutated workbook');
  ok(fxA.problems.some((p) => p.includes(KEY) && /VALUE CHANGED/.test(p)), 'fixture diff NAMES the mutated key');
  const crA = REGEN.crossSourceCheck(wbA.fixture.rates, wbA.matrix);
  ok(!crA.ok, 'cross-source check FAILS on the mutated workbook (Engine sheet now disagrees with tab 2)');
  ok(crA.problems.some((p) => p.includes(KEY)), 'cross-source mismatch NAMES the mutated key');
  // end-to-end through the real CLI + exit code
  const mutAPath = path.join(tmpDir, 'mutated-engine.xlsx');
  fs.writeFileSync(mutAPath, mutatedA);
  const cliA = runCli(['--check', mutAPath]);
  ok(cliA.status === 1, 'CLI --check on the mutated workbook exits 1 (got ' + cliA.status + ')');
  ok(cliA.out.includes(KEY), 'CLI failure output NAMES the mutated key');
  ok(/DRIFT DETECTED/.test(cliA.out), 'CLI reports DRIFT DETECTED');

  /* ================= (4) mutation B: the same cell on TAB 2 only ================= */
  section('mutation: a tab-2 cell trips ONLY the cross-source verifier');
  const rec = wb.matrix.records.find((r) => REGEN.recKey(r) === KEY);
  ok(rec && typeof rec.v === 'number', 'target key located on tab 2 at cell ' + (rec && rec.ref));
  const mutatedB = writeZipStored(mutateCellValue(entries, matrixEntry, rec.ref, '0.5'));
  const wbB = REGEN.readWorkbook(mutatedB);
  ok(REGEN.fixtureCheck(wbB, REGEN.FIXTURE_PATH).ok, 'fixture check still passes (Engine sheet untouched)');
  const crB = REGEN.crossSourceCheck(wbB.fixture.rates, wbB.matrix);
  ok(!crB.ok, 'cross-source check FAILS when tab 2 disagrees with the Engine sheet');
  ok(crB.problems.some((p) => p.includes(KEY) && /MISMATCH/.test(p)), 'cross-source failure NAMES the key');
  // --write must REFUSE while the cross-source contract is broken
  const mutBPath = path.join(tmpDir, 'mutated-tab2.xlsx');
  const refusedOut = path.join(tmpDir, 'refused.json');
  fs.writeFileSync(mutBPath, mutatedB);
  const cliB = runCli(['--write', '--out', refusedOut, '--xlsx', mutBPath]);
  ok(cliB.status === 1, 'CLI --write on a cross-source-broken workbook exits 1 (got ' + cliB.status + ')');
  ok(/REFUSED/.test(cliB.out), 'CLI --write reports the refusal');
  ok(!fs.existsSync(refusedOut), 'refused --write wrote nothing');

  /* ================= (5) --write to an alternate path reproduces the bytes ================= */
  section('--write --out reproduces the committed fixture bytes');
  const outPath = path.join(tmpDir, 'regen.json');
  const cliW = runCli(['--write', '--out', outPath]);
  ok(cliW.status === 0, 'CLI --write --out exits 0 (got ' + cliW.status + ')');
  ok(fs.readFileSync(outPath, 'utf8') === committedText, '--write output is byte-identical to the committed fixture');
  ok(fs.readFileSync(REGEN.FIXTURE_PATH).equals(fixtureBytesBefore), 'committed fixture untouched by --write --out');

  console.log('\nEMCAP regeneration pipeline: ALL ' + passed + ' CHECKS PASSED');
} finally {
  fs.rmSync(tmpDir, { recursive: true, force: true });
}
